import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-overtime.json"), "utf8"),
);
const models = emitModels(contract.models, "overtimeStatusSchema");
let go =
  '// Code generated by scripts/generate-workforce-overtime.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var overtimeStatuses=[]string{${Object.keys(contract.statuses)
  .map((k) => JSON.stringify(k))
  .join(",")}}\n`;
let ts = '// Generated by scripts/generate-workforce-overtime.mjs.\nimport { z } from "zod";\n\n';
ts += `export const OVERTIME_STATUSES=${JSON.stringify(contract.statuses)} as const;\nexport const overtimeStatusSchema=z.enum(${JSON.stringify(Object.keys(contract.statuses))});\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/overtime_types.go",
  go + models.go,
  "packages/api/src/overtime-contract.ts",
  ts + models.ts,
  "overtime",
);
